create table if not exists public.financial_aid_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,award_year text not null default '',fafsa_status text not null default 'Not Started' check(fafsa_status in ('Not Started','Preparing','Submitted','Processed','Corrections Needed','Complete')),started_on date,submitted_on date,contributors_status text not null default 'Not Started',checklist jsonb not null default '{}'::jsonb,notes text not null default '',updated_at timestamptz not null default now());
create table if not exists public.financial_aid_offers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,school_name text not null check(char_length(school_name) between 1 and 160),deadline date,status text not null default 'Waiting',grants numeric(12,2) not null default 0,scholarships numeric(12,2) not null default 0,work_study numeric(12,2) not null default 0,loans numeric(12,2) not null default 0,estimated_cost numeric(12,2) not null default 0,notes text not null default '',updated_at timestamptz not null default now());
create index if not exists financial_aid_offers_user_deadline_idx on public.financial_aid_offers(user_id,deadline);
alter table public.financial_aid_plans enable row level security;alter table public.financial_aid_offers enable row level security;
revoke all on public.financial_aid_plans from anon;revoke all on public.financial_aid_offers from anon;
grant select,insert,update,delete on public.financial_aid_plans to authenticated;grant select,insert,update,delete on public.financial_aid_offers to authenticated;
create policy "Students manage own aid plan" on public.financial_aid_plans for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Students manage own aid offers" on public.financial_aid_offers for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
